use core::sync::atomic::{AtomicU32 as A,Ordering as O};const F:fn(&A,u32,O)->u32=A::fetch_sub;const ORDER:O=O::Release;fn main(){let a=A::new(10);check(F(&a,17,ORDER)==10);check(a.load(O::Relaxed)==4294967289);let f=A::fetch_sub;check(f(&a,1,O::Acquire)==4294967289);let u:unsafe fn(&A,u32,O)->u32=A::fetch_sub;unsafe{check(u(&a,0,O::SeqCst)==4294967288);}check(A::fetch_sub(&a,4294967288,O::AcqRel)==4294967288);check(a.load(O::Relaxed)==0);}
